n":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://rhodeislandinsuranceappraiser.com/#website","url":"https://rhodeislandinsuranceappraiser.com/","name":"Rhode Island Insurance Appraiser","publisher":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#webpage","url":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/","name":"Claim Wordbook | ACV, RCV, Umpire & More Defined","description":"A searchable wordbook of property claim terms: actual cash value, hurricane deductible, ice dam, umpire, storm surge, O&P and more, in plain English.","inLanguage":"en-US","isPartOf":{"@id":"https://rhodeislandinsuranceappraiser.com/#website"},"about":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"publisher":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#primaryimage","url":"https://rhodeislandinsuranceappraiser.com/assets/img/photos/insurance-paperwork.webp","contentUrl":"https://rhodeislandinsuranceappraiser.com/assets/img/photos/insurance-paperwork.webp","width":960,"height":640},"breadcrumb":{"@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#breadcrumb"},"mainEntity":{"@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://rhodeislandinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim wordbook","item":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/"}],"@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property claim wordbook","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is uninhabitable after a covered loss."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It’s what appraisal decides."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal provision","description":"The policy condition that lets either side demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"A competent, disinterested person named by each side to value the loss."},{"@type":"DefinedTerm","name":"Causation","description":"What caused the damage, such as wind versus flood. Usually a coverage question, not an appraisal question."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy condition that can reduce payment if the property is insured below a required percentage of its value."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage: the limit for the house itself on a homeowner policy."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage: detached garages, sheds, fences and similar."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing coverages, limits and deductibles."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age and condition, used to calculate actual cash value."},{"@type":"DefinedTerm","name":"Disinterested","description":"Without a personal stake in the outcome. Policies require appraisers to be disinterested."},{"@type":"DefinedTerm","name":"Dwelling form","description":"A policy form often used for rental properties, which can differ from a standard homeowner form."},{"@type":"DefinedTerm","name":"Endorsement","description":"A form attached to the policy that adds, removes or changes coverage."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state-established insurer of last resort. Rhode Island’s FAIR Plan covers properties that can’t get coverage elsewhere."},{"@type":"DefinedTerm","name":"Flood exclusion","description":"The homeowner policy provision excluding damage from flood and surface water, including storm surge."},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A deductible, usually a percentage of Coverage A, that applies when a storm meets the policy’s hurricane trigger."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under shingles and leak inside."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry on an estimate with a description, quantity, unit and price."},{"@type":"DefinedTerm","name":"Loss of rents","description":"Coverage for rental income lost while a rented unit can’t be lived in after a covered loss."},{"@type":"DefinedTerm","name":"Matching","description":"Whether replacement materials can reasonably match the undamaged remainder of siding, roofing or flooring."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping or drying."},{"@type":"DefinedTerm","name":"Named storm","description":"A tropical storm or hurricane named by the National Hurricane Center, a common hurricane-deductible trigger."},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, which writes most residential flood policies in the U.S."},{"@type":"DefinedTerm","name":"Nor’easter","description":"A coastal storm with strong northeast winds, common in Rhode Island from fall through spring."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting current building codes during repairs."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for managing a job with several trades, often 10% and 10%."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, often due within a set time after the insurer requests it."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Held-back depreciation the policy pays once repairs or replacement are completed."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace with materials of like kind and quality, without deducting depreciation."},{"@type":"DefinedTerm","name":"Scope","description":"The full list of repairs needed, before pricing."},{"@type":"DefinedTerm","name":"Square","description":"A roofing measurement equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Steep charge","description":"An estimate line adding labor for working on steep roofs."},{"@type":"DefinedTerm","name":"Storm surge","description":"Seawater pushed ashore by a storm. Treated as flood under homeowner policies."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy condition limiting how long you have to sue the insurer, often counted from the date of loss."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add missing or underpriced items to a claim after the first estimate."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Wind-driven rain","description":"Rain forced through openings by wind. Coverage depends on whether wind first created an opening."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property repairs."}],"@id":"https://rhodeislandinsuranceappraiser.com/claim-wordbook/#definedtermset"}]}</script>
</head>
